(function () {
  const css = `
    .portfolio__container{max-width:980px!important;padding:.75rem 1rem 1rem!important;overflow:hidden!important;perspective:1400px!important}
    .portfolio__content{width:min(100%,840px)!important;min-height:400px!important;padding:1.85rem!important;gap:1.65rem!important;grid-template-columns:minmax(270px,.95fr) minmax(280px,1.05fr)!important;box-shadow:0 28px 72px rgba(15,23,42,.22)!important}
    .portfolio__img{width:min(100%,380px)!important;height:255px!important;transform:translateX(2.5rem) translateY(-.2rem) rotate(.5deg)!important}
    .portfolio__title{font-size:clamp(1.25rem,1.7vw,1.65rem)!important}.portfolio__description{font-size:.9rem!important;line-height:1.62!important}
    .portfolio__note{display:block!important;color:#b7e7f4!important;font-size:.74rem!important;font-weight:700!important;margin:-.45rem 0 .85rem!important}
    .portfolio__tech{display:flex!important;flex-direction:column!important;align-items:flex-start!important;gap:.55rem!important;margin-bottom:1.15rem!important;max-width:100%!important}
    .portfolio__tech strong{display:block!important;flex-basis:auto!important;margin:0!important;color:#8bd9ee!important;font-size:.72rem!important;letter-spacing:.08em!important;text-transform:uppercase!important}
    .portfolio__tech-chips{display:flex!important;flex-wrap:wrap!important;gap:.45rem!important;align-items:center!important;max-width:100%!important}
    .portfolio__tech-chip{display:inline-flex!important;align-items:center!important;border:1px solid rgba(255,255,255,.15)!important;border-radius:999px!important;background:rgba(255,255,255,.09)!important;color:#e8f7ff!important;font-size:.7rem!important;font-weight:750!important;line-height:1!important;padding:.4rem .58rem!important;white-space:nowrap!important}
    .portfolio__mockup-mapbox{position:relative!important;display:block!important;overflow:hidden!important;background:linear-gradient(135deg,#eef7f8 0%,#d9f0f8 45%,#bfe2ef 100%)!important}
    .portfolio__mockup-mapbox:before{content:'';position:absolute;inset:-16% -10%;background:radial-gradient(circle at 18% 22%,rgba(255,255,255,.9) 0 1px,transparent 2px),linear-gradient(32deg,transparent 0 22%,rgba(255,255,255,.8) 22.3% 23%,transparent 23.3% 100%),linear-gradient(132deg,transparent 0 28%,rgba(255,255,255,.7) 28.2% 28.8%,transparent 29% 100%),linear-gradient(72deg,transparent 0 38%,rgba(255,255,255,.72) 38.2% 39%,transparent 39.2% 100%);background-size:34px 34px,120px 80px,110px 90px,88px 70px;opacity:.72}
    .portfolio__mockup-mapbox .map-area{position:absolute;border:1px solid rgba(255,255,255,.72);background:linear-gradient(135deg,rgba(19,122,171,.88),rgba(80,188,204,.62));box-shadow:inset 0 0 0 1px rgba(14,90,130,.12);clip-path:polygon(13% 8%,94% 2%,88% 36%,97% 58%,76% 92%,32% 84%,7% 56%);opacity:.92}
    .portfolio__mockup-mapbox .map-area:nth-child(1){left:6%;top:9%;width:34%;height:72%;transform:rotate(-10deg)}.portfolio__mockup-mapbox .map-area:nth-child(2){left:35%;top:17%;width:30%;height:54%;transform:rotate(8deg);opacity:.82}.portfolio__mockup-mapbox .map-area:nth-child(3){right:7%;top:22%;width:32%;height:58%;transform:rotate(-4deg)}.portfolio__mockup-mapbox .map-area:nth-child(4){left:28%;bottom:8%;width:40%;height:34%;transform:rotate(5deg);opacity:.78}
    .portfolio__mockup-mapbox .map-dot{position:absolute;width:.82rem;height:.82rem;border:2px solid rgba(255,255,255,.86);border-radius:999px;background:#f97357;box-shadow:0 7px 16px rgba(249,115,87,.25);z-index:2}.portfolio__mockup-mapbox .map-label{position:absolute;z-index:2;color:#102033;font-size:.72rem;font-weight:850;text-shadow:0 1px 0 rgba(255,255,255,.75)}.portfolio__mockup-mapbox .map-badge{position:absolute;left:.75rem;bottom:.75rem;z-index:3;display:inline-flex;align-items:center;gap:.35rem;border:1px solid rgba(16,32,51,.1);border-radius:999px;background:rgba(255,255,255,.86);color:#166a82;font-size:.65rem;font-weight:850;padding:.42rem .58rem;backdrop-filter:blur(10px)}
    .location.section{padding-top:3rem!important;padding-bottom:2.25rem!important}.location__container{margin-top:1.15rem!important}.location__panel,.location__map-card{min-height:18rem!important}.location__map-card{min-height:23rem!important}.location__map{height:15.5rem!important}#location [data-aos]{transition-duration:.52s!important}
    @media(max-width:900px){.portfolio__content{width:100%!important;min-height:auto!important;padding:1rem!important}.portfolio__img{width:100%!important;height:220px!important;transform:none!important}.portfolio__content:after{display:none!important}.location__panel,.location__map-card,.location__weather{min-height:auto!important;transform:none!important}}
  `;

  function injectStyle(){document.getElementById('site-fixes-style')?.remove();const s=document.createElement('style');s.id='site-fixes-style';s.textContent=css;document.head.appendChild(s)}

  function mapboxSlideHtml(){return `
    <div class="portfolio__content">
      <div class="portfolio__img portfolio__mockup-mapbox" role="img" aria-label="Mapbox Power BI Visual mockup with blue catchment layers and sales markers">
        <span class="map-area"></span><span class="map-area"></span><span class="map-area"></span><span class="map-area"></span>
        <span class="map-dot" style="left:18%;top:30%"></span><span class="map-dot" style="left:31%;top:54%"></span><span class="map-dot" style="left:48%;top:36%"></span><span class="map-dot" style="left:62%;top:61%"></span><span class="map-dot" style="left:76%;top:42%"></span><span class="map-dot" style="left:83%;top:68%"></span>
        <span class="map-label" style="left:12%;top:47%">Catchment</span><span class="map-label" style="left:45%;top:27%">Coverage</span><span class="map-label" style="right:12%;bottom:28%">Sales</span>
        <span class="map-badge"><i class="uil uil-map"></i> Mapbox GL JS</span>
      </div>
      <div>
        <h3 class="portfolio__title">Mapbox Power BI Visual</h3>
        <p class="portfolio__description">Developed my own version of an open-source Mapbox visual for Power BI. Added automatic zoom and multi-layer mapping to analyse catchment areas, sales locations, coverage, and potential cannibalisation.</p>
        <p class="portfolio__tech"><strong>Tech Used:</strong> Power BI, TypeScript, JavaScript, Mapbox GL JS</p>
        <span class="portfolio__note">AI-generated mockup using synthetic data.</span>
        <a href="#" class="portfolio__btn">In Progress <i class="uil uil-arrow-right"></i></a>
      </div>
    </div>`}

  function addMapboxPortfolio(){const wrapper=document.querySelector('#portfolio .swiper-wrapper');if(!wrapper)return;let slide=document.querySelector('[data-project="mapbox-powerbi"]');if(!slide){slide=document.createElement('div');slide.className='swiper-slide';slide.dataset.project='mapbox-powerbi';slide.innerHTML=mapboxSlideHtml()}if(wrapper.firstElementChild!==slide)wrapper.insertBefore(slide,wrapper.firstElementChild);const swiper=document.querySelector('.portfolio__container')?.swiper;if(swiper){swiper.update();swiper.pagination?.render?.();swiper.pagination?.update?.();swiper.slideTo(0,0)}}

  function fixPortfolioTech(){document.querySelectorAll('.portfolio__tech').forEach(tech=>{const chips=[...tech.querySelectorAll('.portfolio__tech-chip')];if(tech.querySelector('.portfolio__tech-chips'))return;const label=tech.querySelector('strong')||document.createElement('strong');label.textContent='Tech Used:';const row=document.createElement('span');row.className='portfolio__tech-chips';if(chips.length){chips.forEach(c=>row.appendChild(c))}else{tech.textContent.replace(/Tech Used:/i,'').replace(/\s+/g,' ').trim().split(',').map(x=>x.trim()).filter(Boolean).forEach(x=>{const chip=document.createElement('span');chip.className='portfolio__tech-chip';chip.textContent=x;row.appendChild(chip)})}tech.innerHTML='';tech.append(label,row)})}

  function tuneLocationReveal(){const loc=document.getElementById('location');if(!loc)return;loc.querySelectorAll('.location__panel,.location__map-card,[data-aos]').forEach((el,i)=>{el.setAttribute('data-aos','fade-up');el.setAttribute('data-aos-offset','45');el.setAttribute('data-aos-delay',String(Math.min(i*35,90)));el.setAttribute('data-aos-duration','520')});if(window.AOS){window.AOS.init({offset:80,duration:650,once:false});window.AOS.refreshHard?.();window.AOS.refresh?.()}}

  function runFixes(){injectStyle();addMapboxPortfolio();fixPortfolioTech();tuneLocationReveal()}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',runFixes);else runFixes();
  setTimeout(runFixes,400);setTimeout(runFixes,1400);setTimeout(runFixes,2600);setTimeout(runFixes,4200);setTimeout(runFixes,6500);
})();
